def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    S = np.ones((n, 1))
    if len(labs) > 1:
        st = np.array(feats.stratum)
        S = np.column_stack([np.ones(n)] + [(st == l).astype(float) for l in labs[1:]])
    R = np.corrcoef(X, rowvar=False)

    def ll(M):
        b = np.zeros(M.shape[1])
        for _ in range(30):
            eta = np.clip(M @ b, -30, 30); mu = 1 / (1 + np.exp(-eta))
            W = mu * (1 - mu) + 1e-9
            H = M.T @ (M * W[:, None]) + 1e-6 * np.eye(M.shape[1])
            step = np.linalg.solve(H, M.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        eta = np.clip(M @ b, -30, 30)
        return float(np.sum(y * eta - np.logaddexp(0, eta)))

    def design_mat(sel, prods=()):
        cols = [S] + [X[:, [j]] for j in sel] + [(X[:, a] * X[:, b])[:, None] for a, b in prods]
        return np.hstack(cols)

    sel = []; base = ll(S)
    for k in range(8):
        alpha = (0.1 if k == 0 else 0.01) / p
        best, bj = None, None
        for j in range(p):
            if j in sel or any(abs(R[j, s]) >= 0.6 for s in sel): continue
            v = ll(design_mat(sel + [j]))
            if best is None or v > best: best, bj = v, j
        if bj is None or stats.chi2.sf(2 * (best - base), 1) > alpha: break
        sel.append(bj); base = best
    changed = True
    while changed and len(sel) > 1:
        changed = False; full = ll(design_mat(sel))
        pv = [stats.chi2.sf(2 * (full - ll(design_mat([s for s in sel if s != j]))), 1) for j in sel]
        w = int(np.argmax(pv))
        if pv[w] > 0.01 / p: sel.pop(w); changed = True
    prods = []; full = ll(design_mat(sel)); npairs = p * (p + 1) / 2; cand = []
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            mains = sorted(set(sel) | {a, b})
            m0 = ll(design_mat(mains)); m1 = ll(design_mat(mains, [(a, b)]))
            pv = stats.chi2.sf(2 * (m1 - m0), 1)
            if pv < 0.01 / npairs: cand.append((pv, a, b))
    cand.sort()
    for pv, a, b in cand[:1]:
        prods.append((a, b))
        for j in (a, b):
            if j not in sel: sel.append(j)
    drivers = []
    for j in sel + [j for pr in prods for j in pr]:
        if ids[j] not in drivers: drivers.append(ids[j])
    return Design(drivers=tuple(drivers[:MAX_DRIVERS]), columns=tuple(ids[j] for j in sel),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

